import java.util.*;
public class G{
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        TaskE solver = new TaskE();
        solver.solve(1, in);
        in.close();
    }
    static class TaskE {
        class MinCostMaxFlow{
            ArrayList<Edge> al[];
            Edge ja[][]; 
            int d[]; 
            int N , S , T , maxFlow ; int minCost;
            final int gmax = Integer.MAX_VALUE / 100;

            class Edge{
                int u , flow, rid, cost;
                Edge(int a, int b, int c, int d){u = a; flow = b; cost = c; rid = d;}
            }

            void addEdge(int u , int v , int flow , int cost){
                int lu = al[u].size(), lv = al[v].size();
                al[u].add(new Edge(v, flow, cost, lv)); 
                al[v].add(new Edge(u, 0, -cost, lu));   
            }

            void convertToArray(){
                ja = new Edge[N][];
                for(int i = 0; i < N; i++){
                    int sz = al[i].size();
                    ja[i] = new Edge[sz];
                    for(int j = 0; j < sz; j++){
                        ja[i][j] = al[i].get(j);
                    }
                    al[i].clear();
                }
            }

            MinCostMaxFlow(int n , int source , int sink){
                N = n; S = source; T = sink; maxFlow = 0; minCost = 0;
                al = new ArrayList[N];
                d = new int[N];
                for(int i = 0; i < N; i++){
                    al[i] = new ArrayList<>();
                }
            }

            boolean BellmanFord(boolean check){
                d[0] = 0;
                for(int i = 0; i < N - 1; i++){
                    for(int j = 0; j < N; j++){
                        for(Edge e : ja[j]){
                            if(e.flow == 0)continue;
                            d[e.u] = Math.min(d[e.u] , d[j] + e.cost);
                        }
                    }
                }
                if(check){
                    for(int j = 0; j < N; j++){
                        for(Edge e : ja[j]){
                            if(e.flow == 0)continue;
                            if(d[j] + e.cost < d[e.u]) return false;
                        }
                    }   
                }return true;
            }

            int node[]; 
            int visit[]; 
            int prv[], prve[]; 
            int dist[]; 

            boolean simple(){
                node = new int[N]; 
                visit = new int[N]; 
                prv = new int[N];
                prve = new int[N];
                dist = new int[N];   Arrays.fill(dist , gmax);

                node[0] = S; dist[0] = 0;
                int front = 1, back = 0;
                while(front != back){
                    int u = node[back++]; int distu = dist[u];
                    if(back == N)back = 0;
                    visit[u] = 2;
                    for(int i = 0; i < ja[u].length; i++){
                        Edge e = ja[u][i];
                        if(e.flow == 0)continue;
                        int cdist = distu + e.cost;
                        if(cdist < dist[e.u]){
                            if(visit[e.u] == 0){
                                node[front] = e.u; 
                                if(++front == N)front = 0;
                            }else if(visit[e.u] == 2){
                                if(--back == -1)back += N;
                                node[back] = e.u;
                            }
                            visit[e.u] = 1;
                            prve[e.u] = i; prv[e.u] = u; dist[e.u] = cdist;
                        }
                    }
                }
                return visit[T] != 0;
            }

            class pair{
                int F; int S;
                pair(int a, int b){F = a; S = b;}
            }

            boolean dijkstra(){
                visit = new int[N];
                prv = new int[N];
                prve = new int[N];
                dist = new int[N]; Arrays.fill(dist, gmax);
                PriorityQueue<pair> pq = new PriorityQueue<>((A, B) -> Double.compare(A.S , B.S));

                pq.add(new pair(S , 0)); dist[0] = 0;
                o : while(!pq.isEmpty()){
                    pair p = pq.poll();
                    while(dist[p.F] < p.S){
                        if(pq.isEmpty()) break o; 
                        p = pq.poll();
                    }
                    visit[p.F] = 2;
                    for(int i = 0; i < ja[p.F].length; i++){
                        Edge e = ja[p.F][i];
                        if(e.flow == 0)continue;
                        int cdist = p.S + (e.cost + d[p.F] - d[e.u]);
                        if(cdist < dist[e.u]){ 
                            if(visit[e.u] == 2) return false;
                            pq.add(new pair(e.u , cdist));
                            dist[e.u] = cdist; prv[e.u] = p.F; prve[e.u] = i;
                            visit[e.u] = 1;
                        }
                    }
                }
                return visit[T] != 0;
            }

            int augment(){
                int p = T; int min = gmax;
                while(p != 0){
                    int pp = prv[p], pe = prve[p];
                    int val = ja[pp][pe].flow;
                    min = Math.min(min , val);
                    p = pp;
                }
                p = T;
                while(p != 0){
                    int pp = prv[p], pe = prve[p];
                    ja[pp][pe].flow -= min;
                    ja[p][ja[pp][pe].rid].flow += min;
                    p = pp;
                }
                maxFlow += min;
                return min;
            }

            boolean calSimple(){
                while(simple()){
                    minCost += dist[T] * augment();
                }
                return true;
            }

            void updPotential(){
                for(int i = 0; i < N; i++){
                    if(visit[i] != 0){
                        d[i] += dist[i] - dist[S];
                    }
                }
            }
            boolean calWithPotential(){
                while(dijkstra()){
                    int min = dist[T] + d[T] - d[S];
                    minCost += min * augment();
                    updPotential();
                }
                return true;   
            }
        }
        int n , m, k, c, d, a[], f[];
       public void solve(int testNumber, Scanner in) {
        n = in.nextInt(); m = in.nextInt(); k = in.nextInt(); c = in.nextInt(); d= in.nextInt();
        int maxl = n + k, T = n * maxl + 1;
        MinCostMaxFlow ans = new MinCostMaxFlow(T + 1, 0, T);
        a = new int[k + 1]; f = new int[n + 1];
        for(int i = 1; i <= k; i++){
            a[i] = in.nextInt();
            f[a[i]]++;
        }
        for(int i = 1; i <= n; i++){
            if(f[i] == 0)continue;
            ans.addEdge(0 , i , f[i], 0);
        }
        for(int i = 2; i <= n; i++){
            for(int l = 0; l < maxl - 1; l++){
                ans.addEdge(l * n + i , (l + 1) * n + i, k, c);
            }
        }
        for(int i = 1; i <= m; i++){
            int a = in.nextInt(), b = in.nextInt();
            for(int l = 0; l < maxl - 1; l++){
                for(int p = 1; p <= k; p++){
                    if(a != 1)
                        ans.addEdge(n * l + a, n * (l + 1) + b, 1, d * (2 * p - 1) + c);
                    if(b != 1)
                        ans.addEdge(n * l + b, n * (l + 1) + a, 1, d * (2 * p - 1) + c);
                }
            } 
        }
        for(int l = 1; l < maxl; l++){
            ans.addEdge(l * n + 1, T, k, 0);
        }
        ans.convertToArray();
        ans.calWithPotential();
        if(ans.maxFlow != k){
            System.out.println("BUG");
        }else{
            System.out.println((int)ans.minCost);
        }
      }
    }
}
